package com.graphhopper.routing.util;

import org.junit.jupiter.api.Test;
import org.locationtech.jts.geom.Coordinate;
import org.locationtech.jts.geom.GeometryFactory;
import org.locationtech.jts.geom.Point;
import org.locationtech.jts.index.strtree.STRtree;
import java.util.ArrayList;
import java.util.List;

public class AreaIndexquery_GeometryFactorycreatePointFikaTest {

    @Test
    public void testQueryInvokesGeometryFactoryCreatePoint() {
        // Create real GeometryFactory
        GeometryFactory gf = new GeometryFactory();

        // Create a simple custom area that will intersect with the point
        IndexedCustomArea<String> area = new IndexedCustomArea<>() {
            @Override
            public boolean intersects(Point point) {
                return true; // Always intersect to ensure filter passes
            }
        };
        area.area = "testArea";

        // Create STRtree index and add the custom area
        STRtree index = new STRtree();
        Envelope env = new Envelope(1.0, 1.0, 2.0, 2.0);
        index.insert(env, area);

        // Build query method
        List<String> result = query(gf, index, 2.0, 1.0);
    }

    // Replicate the query method structure from the source
    private <T> List<T> query(GeometryFactory gf, STRtree index, double lat, double lon) {
        Envelope searchEnv = new Envelope(lon, lon, lat, lat);
        @SuppressWarnings("unchecked")
        List<IndexedCustomArea<T>> result = index.query(searchEnv);
        // This line should invoke GeometryFactory.createPoint(...)
        Point point = gf.createPoint(new Coordinate(lon, lat));
        return result.stream()
                .filter(c -> c.intersects(point))
                .map(c -> c.area)
                .collect(java.util.stream.Collectors.toList());
    }

    // Helper classes to support the test
    private static class Envelope {
        private final double minX, maxX, minY, maxY;

        public Envelope(double x1, double x2, double y1, double y2) {
            this.minX = Math.min(x1, x2);
            this.maxX = Math.max(x1, x2);
            this.minY = Math.min(y1, y2);
            this.maxY = Math.max(y1, y2);
        }
