        when(pointList.size()).thenReturn(1);
        when(pointList.getLat(anyInt())).thenReturn(4.0);
        when(pointList.getLon(anyInt())).thenReturn(5.0);
        when(edgeIteratorState.get(EdgeIteratorState.REVERSE_STATE)).thenReturn(false);

