        triangulator.triangulate(snap, queryGraph, shortestPathTree, fz, 0.0);
    }

    // Helper classes to satisfy compilation
    static class JTSTriangulator {
        RouterConfig routerConfig;

        public Result triangulate(Snap snap, QueryGraph queryGraph, ShortestPathTree shortestPathTree,
                                  ToDoubleFunction<ShortestPathTree.IsoLabel> fz, double tolerance) {
            final NodeAccess na = queryGraph.getNodeAccess();
            Collection<Coordinate> sites = new ArrayList<>();
            shortestPathTree.search(snap.getClosestNode(), label -> {
                double exploreValue = fz.applyAsDouble(label);
                double lat = na.getLat(label.node);
                double lon = na.getLon(label.node);
