        }
    }

    // Supporting classes to make the test compile
    static class Result {
        Result(ReadableTriangulation triangulation, Collection<Edge> edges) {}
    }

    static class ReadableTriangulation {
        static ReadableTriangulation wrap(QuadEdgeSubdivision tin) {
            return new ReadableTriangulation();
