            PrepareGraphEdgeIterator setBaseNode(int node);
        }

        interface OrigOutExplorer {
            PrepareGraphOrigEdgeIterator setBaseNode(int node);
        }

        static class PrepareGraphEdgeIterator {
            boolean next() { return false; }
            int getAdjNode() { return 0; }
            double getWeight() { return 0.0; }
            int getOrigEdgeKeyFirst() { return 0; }
            int getOrigEdgeKeyLast() { return 0; }
            int getOrigEdgeCount() { return 0; }
            CHEdgeIteratorState getPrepareEdge() { return null; }
        }

        static class PrepareGraphOrigEdgeIterator {
            boolean next() { return false; }
            int getOrigEdgeKeyFirst() { return 0; }
        }

        PriorityQueue<PrepareCHEntry> queue;
        IntObjectMap<PrepareCHEntry> map;
        final Graph graph;
        final OutExplorer outExplorer;
        final OrigOutExplorer origOutExplorer;

