            this.graph = graph;
            this.outExplorer = outExplorer;
            this.origOutExplorer = origOutExplorer;
        }

        public IntObjectMap<BridePathEntry> find(int startInEdgeKey, int startNode, int centerNode) {
            queue.clear();
            map.clear();
            IntObjectMap<BridePathEntry> result = new IntObjectHashMap<>(16, 0.5, HashOrderMixing.constant(123));
            PrepareCHEntry startEntry = new PrepareCHEntry(null, startInEdgeKey, startInEdgeKey, startNode, 0, 0);
