                this.firstEdgeKey = firstEdgeKey;
                this.incEdgeKey = incEdgeKey;
                this.adjNode = adjNode;
                this.weight = weight;
                this.origEdges = origEdges;
            }
        }

        static class BridePathEntry {
            double weight;
            PrepareCHEntry chEntry;

            BridePathEntry(double weight, PrepareCHEntry chEntry) {
                this.weight = weight;
                this.chEntry = chEntry;
            }
