        // i.e. we force turning onto the artificial edge we created for this in-edge
        for (BooleanEncodedValue turnRestrictionEnc : turnRestrictionEncs) {
            restrictTurn(turnRestrictionEnc, incomingEdge, node, viaEdge);
        }
