        File tempFile = tempDir.resolve("test.tif").toFile();

        // Create a minimal valid TIFF header
        try (FileOutputStream fos = new FileOutputStream(tempFile)) {
            // TIFF header: Byte order (II for little-endian)
            fos.write(0x49); // 'I'
            fos.write(0x49); // 'I'

            // Version number (42)
            fos.write(0x2A);
            fos.write(0x00);

            // Offset to first IFD (8 bytes from start)
            fos.write(0x08);
            fos.write(0x00);
            fos.write(0x00);
            fos.write(0x00);

            // First IFD: Number of directory entries (0)
            fos.write(0x00);
            fos.write(0x00);

            // Offset to next IFD (0 - no more IFDs)
            fos.write(0x00);
            fos.write(0x00);
            fos.write(0x00);
            fos.write(0x00);
        }

        return tempFile;
    }

