package com.graphhopper.util;

import com.carrotsearch.hppc.IntArrayList;
import com.graphhopper.util.GHUtility;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Method;

class GHUtilitypathsEqualExceptOneEdge_IntArrayListsizeFikaTest {

    @Test
    void testIntArrayListSizeInvocation() throws Exception {
        // Create paths with size difference of 1
        IntArrayList p1 = new IntArrayList();
        p1.add(1);
        p1.add(2);
        p1.add(3);

        IntArrayList p2 = new IntArrayList();
        p2.add(1);
        p2.add(99); // Different middle node
        p2.add(3);
        p2.add(4); // Makes p2 longer by 1

        // Create a simple graph that will make the distance check pass
        Graph graph = new Graph() {
            @Override
            public double getMinDist(int from, int to) {
                // Return distances that satisfy distABC ≈ distAC
                if ((from == 1 && to == 3) || (from == 3 && to == 1)) {
                    return 2.0; // distAC
                }
                if ((from == 1 && to == 99) || (from == 99 && to == 1)) {
                    return 1.0; // A-B
                }
                if ((from == 99 && to == 3) || (from == 3 && to == 99)) {
                    return 1.0; // B-C
                }
                return 0.0;
            }
        };

        // Use reflection to access the private method
        Method method = GHUtility.class.getDeclaredMethod(
            "pathsEqualExceptOneEdge", 
            Graph.class, 
            IntIndexedContainer.class, 
            IntIndexedContainer.class
        );
        method.setAccessible(true);

        // This will execute the method and reach indicesWithDifferentNodes.size()
        method.invoke(null, graph, p1, p2);
    }

    // Minimal Graph interface implementation
    private interface Graph {
        double getMinDist(int from, int to);
    }

    // Minimal IntIndexedContainer interface
    private interface IntIndexedContainer {
        int size();
        int get(int index);
        boolean equals(Object other);
    }

    // Extend IntArrayList to implement IntIndexedContainer
    private static class TestIntArrayList extends IntArrayList implements IntIndexedContainer {
        public TestIntArrayList(int... elements) {
            for (int e : elements) {
                add(e);
            }
        }
    }
}

