    long longitude = 0;
    // int userId = 0;
    // int userSid = 0;
    // long timestamp = 0;
    // long changesetId = 0;
    for (int i = 0; i < idList.size(); i++) {
        // Delta decode node fields.
        nodeId += idList.get(i);
        latitude += latList.get(i);
        longitude += lonList.get(i);
        /* if (denseInfo != null) {
