            LOGGER.info((((("Made " + blockedEdges.size()) + " edges inaccessible. Calculated country cut in ") + sw.stop().getSeconds()) + "s, ") + Helper.getMemInfo());

    } else {
        blockedEdges = new IntHashSet();
