        LOGGER.info((((("Calculated " + graphComponents.getComponents().size()) + " subnetworks via tarjan in ") + sw.stop().getSeconds()) + "s, ") + Helper.getMemInfo());

    String additionalInfo = "";
    // guess the factor
    if (factor <= 0) {
