                        jsonFeatureCollections.add(jsonFeatureCollection);
                    }
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return jsonFeatureCollections.stream().flatMap(j -> j.getFeatures().stream()).map(feature -> new Object()).collect(Collectors.toList());
        }
    }

    private static class JsonFeatureCollection {
        private List<Object> features = new ArrayList<>();

        public List<Object> getFeatures() {
            return features;
        }
    }
}

