}

protected void flush() {
    logger.info(((((("flushing graph " + getBaseGraphString()) + ", details:") + baseGraph.toDetailsString()) + ", ") + getMemInfo()) + ")");
    baseGraph.flush();
    properties.flush();
    logger.info(("flushed graph " + getMemInfo()) + ")");
    setFullyLoaded();
}

