        // Create an instance of the class containing readCustomAreas()
        Object testInstance = new Object() {
            private String customAreasDirectory = tempDir.toString();

            private List<Object> readCustomAreas() {
                ObjectMapper objectMapper = new ObjectMapper();
                objectMapper.registerModule(new JtsModule());
                // The rest of the method would execute but we don't need it to complete
                // The JtsModule constructor has been invoked which was our goal
                return List.of();
            }
        };

        // Use reflection to invoke the private method
        try {
            var method = testInstance.getClass().getDeclaredMethod("readCustomAreas");
            method.setAccessible(true);
            method.invoke(testInstance);
        } catch (Exception e) {
            // Ignore exceptions - our goal was just to reach the JtsModule constructor
        }
    }
}

