    @Test
    public void testReadCustomAreas() throws IOException {
        // Create a minimal valid GeoJSON file
        String geoJsonContent = """
            {
                "type": "FeatureCollection",
                "features": []
            }
            """;

        Path geoJsonFile = tempDir.resolve("test.geojson");
        Files.writeString(geoJsonFile, geoJsonContent, StandardOpenOption.CREATE);

