        // We'll use a concrete implementation that provides the necessary directory
        TestGraphHopper graphHopper = new TestGraphHopper(tempDir.toString());

        // Invoke the method - this will trigger ObjectMapper.<init>()
        graphHopper.readCustomAreas();
    }

    // Concrete implementation that exposes the method and provides directory
    private static class TestGraphHopper {
        private final String customAreasDirectory;

        public TestGraphHopper(String customAreasDirectory) {
            this.customAreasDirectory = customAreasDirectory;
        }

        private java.util.List<Object> readCustomAreas() {
            com.fasterxml.jackson.databind.ObjectMapper objectMapper = new com.fasterxml.jackson.databind.ObjectMapper();
            objectMapper.registerModule(new org.wololo.jts2geojson.JtsModule());
            final java.nio.file.Path bordersDirectory = java.nio.file.Paths.get(customAreasDirectory);
