            try (java.nio.file.DirectoryStream<java.nio.file.Path> stream = 
                    java.nio.file.Files.newDirectoryStream(bordersDirectory, "*.{geojson,json}")) {
                for (java.nio.file.Path borderFile : stream) {
                    try (java.io.BufferedReader reader = 
                            java.nio.file.Files.newBufferedReader(borderFile, java.nio.charset.StandardCharsets.UTF_8)) {
                        Object jsonFeatureCollection = objectMapper.readValue(reader, Object.class);
                        jsonFeatureCollections.add(jsonFeatureCollection);
                    }
                }
            } catch (java.io.IOException e) {
                throw new java.io.UncheckedIOException(e);
            }
            return jsonFeatureCollections;
        }
    }
}

