private QueryOverlay build(List<Snap> resList) // PATH: Test should invoke the next QueryOverlayBuilder.buildEdgeChangesAtRealNodes(...) [step in execution path]
{
    queryOverlay = new QueryOverlay(resList.size(), is3D);
    buildVirtualEdges(resList);
    buildEdgeChangesAtRealNodes();
    return queryOverlay;
}

private void buildEdgeChangesAtRealNodes() // PATH: Test should invoke the next EdgeChangeBuilder.build(...) [step in execution path]
{
    EdgeChangeBuilder.build(queryOverlay.getClosestEdges(), queryOverlay.getVirtualEdges(), firstVirtualNodeId, queryOverlay.getEdgeChangesAtRealNodes());
}

/**
 * Builds a mapping between real node ids and the set of changes for their adjacent edges.
 *
 * @param edgeChangesAtRealNodes
 * 		output parameter, you need to pass an empty & modifiable map and the results will
 * 		be added to it
 */
static void build(IntArrayList closestEdges, List<VirtualEdgeIteratorState> virtualEdges, int firstVirtualNodeId, IntObjectMap<QueryOverlay.EdgeChanges> edgeChangesAtRealNodes) // PATH: Test should invoke the next new EdgeChangeBuilder(...) [step in execution path]
{
    new EdgeChangeBuilder(closestEdges, virtualEdges, firstVirtualNodeId, edgeChangesAtRealNodes).build();
}

private EdgeChangeBuilder(IntArrayList closestEdges, List<VirtualEdgeIteratorState> virtualEdges, int firstVirtualNodeId, IntObjectMap<QueryOverlay.EdgeChanges> edgeChangesAtRealNodes) {
    this.closestEdges = closestEdges;
    this.virtualEdges = virtualEdges;
    this.firstVirtualNodeId = firstVirtualNodeId;
    if (!edgeChangesAtRealNodes.isEmpty()) {
